import { useI18n } from './i18n'
import { workbenchText } from './workbenchEnglish'
import { useEffect, useMemo, useRef, useState, type PointerEvent as ReactPointerEvent, type WheelEvent as ReactWheelEvent } from 'react'
import { anchorPoint, componentRegistry, createNodeMoveUpdate, defaultEntityType, deleteUnreferencedEvidence, emptyIllustration, entityLabels, evidenceLabels, flowPoints, migrateIllustration, orthogonalPoints, pointsPath, relationLabels, selectionBounds, validateIllustration, type AnchorId, type ComponentDefinition, type ComponentId, type DocumentKind, type EntityType, type EvidenceType, type IllustrationNode, type IllustrationSection, type IllustrationSpec, type RelationType } from './illustration'
import './IllustrationStudio.css'
import { mechanismRelationLabelPosition, mechanismRelationStyle, mechanismRelationStyleVersion } from './illustrationMechanismStyle'
